svg.script:

(function() {
  const svg = document.getElementById('db-interactive-svg');
  const handle = document.getElementById('slider-handle');
  const track = document.getElementById('slider-track');
  const fill = document.getElementById('slider-fill');
  const cursor = document.getElementById('cursor-line');
  const ptDem = document.getElementById('point-demencia');
  const ptDel = document.getElementById('point-delirium');
  const trigger = document.getElementById('hotspot-trigger');

  const demPoints = [
    {x: 100, y: 155}, {x: 200, y: 185}, {x: 300, y: 220},
    {x: 400, y: 255}, {x: 500, y: 290}, {x: 600, y: 330}
  ];

  const delPoints = [
    {x: 100, y: 140}, {x: 195, y: 140}, {x: 205, y: 390},
    {x: 240, y: 260}, {x: 280, y: 410}, {x: 330, y: 240},
    {x: 380, y: 390}, {x: 430, y: 210}, {x: 480, y: 300},
    {x: 530, y: 150}, {x: 600, y: 140}
  ];

  const phases = [
    {
      minX: 100, maxX: 195,
      title: "FASE 1: NÍVEL BASAL DO PACIENTE",
      delStatus: "Cognição Preservada (100%)",
      delL1: "Paciente ativo, alerta e atento.",
      delL2: "Nenhum sinal de confusão mental.",
      demStatus: "Declínio Leve Progressivo",
      demL1: "Perda gradual de memória recente.",
      demL2: "Nível de alerta e atenção normais.",
      lessonL1: "No basal, a demência já apresenta declínio",
      lessonL2: "insidioso há meses. O delirium ainda não",
      lessonL3: "ocorreu. A atenção de ambos está normal."
    },
    {
      minX: 195, maxX: 225,
      title: "FASE 2: GATILHO E QUEDA AGUDA",
      delStatus: "Delirium Agudo Instalado",
      delL1: "Queda súbita da atenção (horas/dias).",
      delL2: "Déficit grave de foco e desorientação.",
      demStatus: "Evolução Lenta Inalterada",
      demL1: "Demência prossegue seu curso estável.",
      demL2: "Sem mudanças agudas ou súbitas.",
      lessonL1: "O delirium surge de forma abrupta, comumente",
      lessonL2: "por fator orgânico (infecção, dor, drogas).",
      lessonL3: "A demência não apresenta quedas súbitas."
    },
    {
      minX: 225, maxX: 400,
      title: "FASE 3: OSCILAÇÃO E FLUTUAÇÃO",
      delStatus: "Flutuação Ativa e Severa",
      delL1: "Momentos de agitação/letargia mistos.",
      delL2: "Presença de 'intervalos lúcidos' no dia.",
      demStatus: "Declínio Estável Linear",
      demL1: "Comprometimento progressivo e constante.",
      demL2: "Sem oscilação horária ou diurna.",
      lessonL1: "A flutuação horária da atenção é a marca",
      lessonL2: "registrada do delirium. A demência declina",
      lessonL3: "sem apresentar estas oscilações severas."
    },
    {
      minX: 400, maxX: 530,
      title: "FASE 4: TRATAMENTO E CONVALESCENÇA",
      delStatus: "Recuperação do Basal",
      delL1: "Atenção melhora após tratar a causa de",
      delL2: "base (ex: cura de infecção urinária).",
      demStatus: "Déficit Irreversível",
      demL1: "O declínio cortical continua progredindo.",
      demL2: "Não há retorno ao basal ou melhora.",
      lessonL1: "O delirium é uma condição aguda reversível na",
      lessonL2: "maioria dos casos. O declínio cognitivo da",
      lessonL3: "demência é permanente, crônico e progressivo."
    },
    {
      minX: 530, maxX: 600,
      title: "FASE 5: AVALIAÇÃO A LONGO PRAZO",
      delStatus: "Resolução Completa (100%)",
      delL1: "Paciente recuperou sua atenção basal.",
      delL2: "Estado cognitivo de base reestabelecido.",
      demStatus: "Declínio Avançado Consolidado",
      demL1: "Perda funcional e de autonomia severas.",
      demL2: "Paciente requer assistência continuada.",
      lessonL1: "O tempo é o melhor diferencial diagnóstico:",
      lessonL2: "o delirium é transitório e resolvido, enquanto",
      lessonL3: "a demência progride irreversivelmente."
    }
  ];

  function getY(x, points) {
    if (x <= points[0].x) return points[0].y;
    if (x >= points[points.length - 1].x) return points[points.length - 1].y;
    for (let i = 0; i < points.length - 1; i++) {
      const p1 = points[i];
      const p2 = points[i+1];
      if (x >= p1.x && x <= p2.x) {
        const t = (x - p1.x) / (p2.x - p1.x);
        return p1.y + t * (p2.y - p1.y);
      }
    }
    return points[0].y;
  }

  function update(x) {
    x = Math.max(100, Math.min(600, x));
    handle.setAttribute('cx', x);
    fill.setAttribute('width', x - 100);
    cursor.setAttribute('x1', x);
    cursor.setAttribute('x2', x);

    const yDem = getY(x, demPoints);
    const yDel = getY(x, delPoints);
    ptDem.setAttribute('cx', x);
    ptDem.setAttribute('cy', yDem);
    ptDel.setAttribute('cx', x);
    ptDel.setAttribute('cy', yDel);

    const phase = phases.find(p => x >= p.minX && x < p.maxX) || phases[phases.length - 1];
    document.getElementById('phase-title').textContent = phase.title;
    document.getElementById('del-status').textContent = phase.delStatus;
    document.getElementById('del-desc-l1').textContent = phase.delL1;
    document.getElementById('del-desc-l2').textContent = phase.delL2;
    document.getElementById('dem-status').textContent = phase.demStatus;
    document.getElementById('dem-desc-l1').textContent = phase.demL1;
    document.getElementById('dem-desc-l2').textContent = phase.demL2;
    document.getElementById('lesson-l1').textContent = phase.lessonL1;
    document.getElementById('lesson-l2').textContent = phase.lessonL2;
    document.getElementById('lesson-l3').textContent = phase.lessonL3;
  }

  let dragging = false;

  function onMove(e) {
    if (!dragging) return;
    const rect = svg.getBoundingClientRect();
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const x = (clientX - rect.left) * (960 / rect.width);
    update(x);
  }

  function startDrag(e) {
    dragging = true;
    if (e.type === 'touchstart') e.preventDefault();
  }

  function stopDrag() {
    dragging = false;
  }

  handle.addEventListener('mousedown', startDrag);
  window.addEventListener('mousemove', onMove);
  window.addEventListener('mouseup', stopDrag);

  handle.addEventListener('touchstart', startDrag, {passive: false});
  window.addEventListener('touchmove', onMove, {passive: true});
  window.addEventListener('touchend', stopDrag);

  track.addEventListener('click', function(e) {
    const rect = svg.getBoundingClientRect();
    const x = (e.clientX - rect.left) * (960 / rect.width);
    update(x);
  });

  handle.addEventListener('keydown', function(e) {
    let x = parseFloat(handle.getAttribute('cx'));
    if (e.key === 'ArrowRight' || e.key === 'ArrowUp') {
      update(x + 10);
      e.preventDefault();
    } else if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') {
      update(x - 10);
      e.preventDefault();
    }
  });

  trigger.addEventListener('click', function() {
    update(200);
  });

  // Inicializa em x=100
  update(100);
})();
